import{readFileSync,writeFileSync,mkdirSync}from'node:fs';import{createProblemExecutor}from'../../../src/analyze/execute-problem.ts';import{localCoreIdentity}from'../../../src/analyze/local-model-cache.ts';import{d1Observables,compareD1}from'./observables.ts';
const joint=process.argv[2],seg=process.argv[3],out=process.argv[4];mkdirSync(out,{recursive:true});const execute=createProblemExecutor(true),names=['input','victimInput','output','victimOutput'];const outputs:any={};
for(const label of ['coarse','fine','domain']){const source=JSON.parse(readFileSync(joint+'/joint-'+label+'.json','utf8')),model=source.report.model,ports=Array.from({length:4},(_,i)=>'p'+i);const r=execute({kind:'frequency-network',request:{instances:[{id:'joint',model:{id:'joint',kind:'network',ports,data:model},ports}],connections:[],ports:names.map((name,index)=>({name,index})),frequencies:source.network.frequenciesHz,representation:'S',referenceOhm:[50,50,50,50],budget:{maxSeconds:60,maxMemoryMiB:1024}}});if(r.status!=='complete')throw Error(JSON.stringify(r.diagnostics));outputs[label]=r;writeFileSync(out+'/joint-'+label+'.json',JSON.stringify(r));}
const request=JSON.parse(readFileSync(seg+'/minimal-assembly-request.json','utf8')),r=execute({kind:'frequency-network',request});writeFileSync(out+'/hybrid.json',JSON.stringify(r));if(r.status!=='complete')throw Error(JSON.stringify(r.diagnostics));
const comparisons={mesh:compareD1(d1Observables(outputs.coarse),d1Observables(outputs.fine),.02),domain:compareD1(d1Observables(outputs.fine),d1Observables(outputs.domain),.02),representations:compareD1(d1Observables(r),d1Observables(outputs.fine),.08)};
writeFileSync(out+'/comparison.json',JSON.stringify({status:'unsupported',core:localCoreIdentity(),sourceJoint:joint,sourceHybrid:seg,reason:'Joint magnetic mesh reference remains unadmitted; comparisons are numerical diagnostics only',comparisons},null,2));console.log(JSON.stringify(comparisons));
